{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12", "C06", "C39", "C03", "C33"],
      "claim": "Multiple direct human measurements for nifedipine place oral bioavailability at 35-68%, consistently above the 20% threshold."
    },
    {
      "card_ids": ["C24", "C26", "C16", "C42"],
      "claim": "Direct absolute or systemic bioavailability values for other transferred molecules are above 20%: 34%, 38%, 50%, and 90% respectively."
    },
    {
      "card_ids": ["C35", "C04", "C08", "C11", "C34", "C10", "C28"],
      "claim": "Some high-transfer evidence supports low bioavailability: isradipine healthy-volunteer values are mostly 16-19%, and pentazocine healthy-subject values are 11-18.5%."
    },
    {
      "card_ids": ["C17", "C21", "C01"],
      "claim": "Rigosertib evidence is mixed: fasting absolute bioavailability is 34.8-35%, but fed bioavailability is 13.9%, creating food-dependent uncertainty."
    },
    {
      "card_ids": ["C02", "C22", "C40"],
      "claim": "Qualitative or provenance-conflicted records are not used as threshold evidence: elagolix is only described as 'good', and molecule 6 combines records for different compounds."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": [
    "C35", "C04", "C18", "C29", "C08", "C11",
    "C34", "C10", "C43", "C23", "C05", "C25", "C31", "C28",
    "C01", "C15"
  ],
  "decision_summary": "After collapsing records by molecule, most high-transfer evidence supports F >= 20% (nifedipine, the C24 compound, nabumetone active metabolite, soraprazan, methocarbamol), while isradipine and pentazocine support low F. The positive evidence is more direct and consistent, so predict high with moderate confidence.",
  "evidence_gaps": [
    "Molecule 6 groups records for different compounds (ORH-2014 and TSU-68), so its positive evidence is discounted.",
    "Molecule 8 has food-dependent bioavailability (35% fasting vs 13.9% fed), leaving condition-dependent uncertainty.",
    "Molecule 4 provides only qualitative 'good' bioavailability without a numeric F value.",
    "Isradipine and pentazocine have cirrhosis values above 20%, but ordinary healthy-condition values are below 20%; altered-condition values were discounted."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": [
    "C12", "C24", "C26", "C16", "C42", "C17"
  ],
  "revision_action": "initial",
  "supportive_card_ids": [
    "C12", "C06", "C39", "C27", "C38", "C37", "C09", "C03", "C30", "C33",
    "C24", "C26", "C16", "C42", "C19", "C17", "C21", "C41", "C07"
  ]
}

